export default {"file":"library-management.html","title":"Library Management - Schoolix","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<div class=\"container\">\r\n\r\n    <!-- Header -->\r\n    <div class=\"card\">\r\n        <div class=\"header-row\">\r\n            <div>\r\n                <h1>Library Staff Management</h1>\r\n                <p class=\"muted\">Create and manage librarian accounts.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Add Librarian -->\r\n    <div class=\"card\">\r\n        <h2 class=\"section-icon\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                <path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/>\r\n            </svg>\r\n            Add Librarian\r\n        </h2>\r\n        <form id=\"addLibrarianForm\">\r\n            <div class=\"form-grid\">\r\n                <input type=\"text\" id=\"librarianName\" placeholder=\"Librarian Name\" required>\r\n                <input type=\"email\" id=\"librarianEmail\" placeholder=\"Librarian Email\" required>\r\n                <input type=\"password\" id=\"librarianPassword\" placeholder=\"Set Password\" required minlength=\"6\">\r\n                <button type=\"submit\" class=\"primary-btn\">Create Librarian Account</button>\r\n            </div>\r\n        </form>\r\n    </div>\r\n\r\n    <!-- Librarians List -->\r\n    <div class=\"card\">\r\n        <h2 class=\"section-icon\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                <path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/>\r\n            </svg>\r\n            Librarians List\r\n        </h2>\r\n        <div id=\"librarianList\"></div>\r\n    </div>\r\n\r\n<script src=\"school-branding.js\"></script>\r\n<script type=\"module\">\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport {\r\n    getAuth,\r\n    createUserWithEmailAndPassword,\r\n    onAuthStateChanged,\r\n    signOut\r\n} from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    setDoc,\r\n    getDoc,\r\n    getDocs,\r\n    collection,\r\n    deleteDoc,\r\n    serverTimestamp,\r\n    query,\r\n    where\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\n\r\n// Secondary app instance for creating new users without affecting admin session\r\nconst staffCreatorApp = initializeApp(firebaseConfig, \"staffCreatorApp\");\r\nconst staffCreatorAuth = getAuth(staffCreatorApp);\r\n\r\nconst librarianForm = document.getElementById(\"addLibrarianForm\");\r\nconst librarianListEl = document.getElementById(\"librarianList\");\r\nlet adminUID = null;\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n    if (!userDoc.exists() || userDoc.data().role !== \"admin\") {\r\n        alert(\"Access denied. Only admin can manage staff.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    adminUID = user.uid;\r\n    loadStaff(\"librarian\", librarianListEl);\r\n});\r\n\r\n// ── Librarian form ──────────────────────────────────────────\r\nlibrarianForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    await createStaff(\r\n        \"librarian\",\r\n        document.getElementById(\"librarianName\").value.trim(),\r\n        document.getElementById(\"librarianEmail\").value.trim().toLowerCase(),\r\n        document.getElementById(\"librarianPassword\").value.trim(),\r\n        librarianForm\r\n    );\r\n});\r\n\r\n// ── Shared create function ───────────────────────────────────\r\nasync function createStaff(role, name, email, password, formEl) {\r\n    const submitBtn = formEl.querySelector(\"button[type='submit']\");\r\n    const originalText = submitBtn.textContent;\r\n    if (!name || !email || !password) {\r\n        alert(\"Please fill all fields.\");\r\n        return;\r\n    }\r\n    try {\r\n        submitBtn.disabled = true;\r\n        submitBtn.textContent = \"Creating...\";\r\n        const userCred = await createUserWithEmailAndPassword(staffCreatorAuth, email, password);\r\n        const uid = userCred.user.uid;\r\n\r\n        await setDoc(doc(db, \"users\", uid), {\r\n            name,\r\n            email,\r\n            role,\r\n            adminId: adminUID,\r\n            schoolId: adminUID,\r\n            createdAt: serverTimestamp(),\r\n            updatedAt: serverTimestamp()\r\n        });\r\n\r\n        alert(`${capitalize(role)} account created successfully.`);\n        formEl.reset();\r\n\r\n        await loadStaff(\"librarian\", librarianListEl);\r\n    } catch (error) {\r\n        alert(error.message);\r\n    } finally {\r\n        submitBtn.disabled = false;\r\n        submitBtn.textContent = originalText;\r\n    }\r\n}\r\n\r\n// ── Shared load function ─────────────────────────────────────\r\nasync function loadStaff(role, listEl) {\r\n    if (!adminUID) return;\r\n    listEl.innerHTML = `<div class=\"empty\">Loading ${role}s...</div>`;\r\n    try {\r\n        const [adminSnap, schoolSnap] = await Promise.all([\r\n            getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", role), where(\"adminId\", \"==\", adminUID))),\r\n            getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", role), where(\"schoolId\", \"==\", adminUID)))\r\n        ]);\r\n        listEl.innerHTML = \"\";\r\n        let count = 0;\r\n        const seen = new Set();\r\n\r\n        [...adminSnap.docs, ...schoolSnap.docs].forEach((docSnap) => {\r\n            if (seen.has(docSnap.id)) return;\r\n            seen.add(docSnap.id);\r\n            const data = docSnap.data();\r\n            count++;\r\n            const row = document.createElement(\"div\");\r\n            row.className = \"list-item\";\r\n            row.innerHTML = `\r\n                <div class=\"list-meta\">\r\n                    <strong>${data.name || \"N/A\"}</strong><br>\r\n                    ${data.email || \"N/A\"}<br>\r\n                    <span class=\"badge badge-librarian\">${capitalize(role)}</span>\r\n                </div>\r\n                <div class=\"item-actions\">\r\n                    <button class=\"secondary-btn\" onclick=\"window.location.href='#/teacher-profile.html?id=${docSnap.id}'\">View Profile</button>\r\n                    <button class=\"danger-btn\" onclick=\"deleteStaff('${docSnap.id}', '${role}')\">Delete</button>\r\n                </div>\r\n            `;\r\n            listEl.appendChild(row);\r\n        });\r\n\r\n        if (count === 0) {\r\n            listEl.innerHTML = `<div class=\"empty\">No ${role}s found.</div>`;\r\n        }\r\n    } catch (error) {\r\n        console.error(`${role} load failed:`, error);\r\n        listEl.innerHTML = `<div class=\"empty\">Unable to load ${role}s: ${error.message}</div>`;\r\n    }\r\n}\r\n\r\n// ── Delete ───────────────────────────────────────────────────\r\nwindow.deleteStaff = async (uid, role) => {\r\n    if (!confirm(`Delete ${role} record?`)) return;\r\n    await deleteDoc(doc(db, \"users\", uid));\r\n    alert(`${capitalize(role)} record deleted.`);\r\n    loadStaff(\"librarian\", librarianListEl);\r\n};\r\n\r\n// ── Logout ───────────────────────────────────────────────────\r\nwindow.logout = async () => {\r\n    try {\r\n        await signOut(auth);\r\n        window.location.href = \"#/index.html\";\r\n    } catch (error) {\r\n        alert(\"Logout failed.\");\r\n    }\r\n};\r\n\r\nfunction capitalize(str) {\r\n    return str.charAt(0).toUpperCase() + str.slice(1);\r\n}\r\n</script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n  <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport {\r\n    getAuth,\r\n    createUserWithEmailAndPassword,\r\n    onAuthStateChanged,\r\n    signOut\r\n} from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    setDoc,\r\n    getDoc,\r\n    getDocs,\r\n    collection,\r\n    deleteDoc,\r\n    serverTimestamp,\r\n    query,\r\n    where\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\n\r\n// Secondary app instance for creating new users without affecting admin session\r\nconst staffCreatorApp = initializeApp(firebaseConfig, \"staffCreatorApp\");\r\nconst staffCreatorAuth = getAuth(staffCreatorApp);\r\n\r\nconst librarianForm = document.getElementById(\"addLibrarianForm\");\r\nconst librarianListEl = document.getElementById(\"librarianList\");\r\nlet adminUID = null;\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n    if (!userDoc.exists() || userDoc.data().role !== \"admin\") {\r\n        alert(\"Access denied. Only admin can manage staff.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    adminUID = user.uid;\r\n    loadStaff(\"librarian\", librarianListEl);\r\n});\r\n\r\n// ── Librarian form ──────────────────────────────────────────\r\nlibrarianForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    await createStaff(\r\n        \"librarian\",\r\n        document.getElementById(\"librarianName\").value.trim(),\r\n        document.getElementById(\"librarianEmail\").value.trim().toLowerCase(),\r\n        document.getElementById(\"librarianPassword\").value.trim(),\r\n        librarianForm\r\n    );\r\n});\r\n\r\n// ── Shared create function ───────────────────────────────────\r\nasync function createStaff(role, name, email, password, formEl) {\r\n    const submitBtn = formEl.querySelector(\"button[type='submit']\");\r\n    const originalText = submitBtn.textContent;\r\n    if (!name || !email || !password) {\r\n        alert(\"Please fill all fields.\");\r\n        return;\r\n    }\r\n    try {\r\n        submitBtn.disabled = true;\r\n        submitBtn.textContent = \"Creating...\";\r\n        const userCred = await createUserWithEmailAndPassword(staffCreatorAuth, email, password);\r\n        const uid = userCred.user.uid;\r\n\r\n        await setDoc(doc(db, \"users\", uid), {\r\n            name,\r\n            email,\r\n            role,\r\n            adminId: adminUID,\r\n            schoolId: adminUID,\r\n            createdAt: serverTimestamp(),\r\n            updatedAt: serverTimestamp()\r\n        });\r\n\r\n        alert(`${capitalize(role)} account created successfully.`);\n        formEl.reset();\r\n\r\n        await loadStaff(\"librarian\", librarianListEl);\r\n    } catch (error) {\r\n        alert(error.message);\r\n    } finally {\r\n        submitBtn.disabled = false;\r\n        submitBtn.textContent = originalText;\r\n    }\r\n}\r\n\r\n// ── Shared load function ─────────────────────────────────────\r\nasync function loadStaff(role, listEl) {\r\n    if (!adminUID) return;\r\n    listEl.innerHTML = `<div class=\"empty\">Loading ${role}s...</div>`;\r\n    try {\r\n        const [adminSnap, schoolSnap] = await Promise.all([\r\n            getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", role), where(\"adminId\", \"==\", adminUID))),\r\n            getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", role), where(\"schoolId\", \"==\", adminUID)))\r\n        ]);\r\n        listEl.innerHTML = \"\";\r\n        let count = 0;\r\n        const seen = new Set();\r\n\r\n        [...adminSnap.docs, ...schoolSnap.docs].forEach((docSnap) => {\r\n            if (seen.has(docSnap.id)) return;\r\n            seen.add(docSnap.id);\r\n            const data = docSnap.data();\r\n            count++;\r\n            const row = document.createElement(\"div\");\r\n            row.className = \"list-item\";\r\n            row.innerHTML = `\r\n                <div class=\"list-meta\">\r\n                    <strong>${data.name || \"N/A\"}</strong><br>\r\n                    ${data.email || \"N/A\"}<br>\r\n                    <span class=\"badge badge-librarian\">${capitalize(role)}</span>\r\n                </div>\r\n                <div class=\"item-actions\">\r\n                    <button class=\"secondary-btn\" onclick=\"window.location.href='#/teacher-profile.html?id=${docSnap.id}'\">View Profile</button>\r\n                    <button class=\"danger-btn\" onclick=\"deleteStaff('${docSnap.id}', '${role}')\">Delete</button>\r\n                </div>\r\n            `;\r\n            listEl.appendChild(row);\r\n        });\r\n\r\n        if (count === 0) {\r\n            listEl.innerHTML = `<div class=\"empty\">No ${role}s found.</div>`;\r\n        }\r\n    } catch (error) {\r\n        console.error(`${role} load failed:`, error);\r\n        listEl.innerHTML = `<div class=\"empty\">Unable to load ${role}s: ${error.message}</div>`;\r\n    }\r\n}\r\n\r\n// ── Delete ───────────────────────────────────────────────────\r\nwindow.deleteStaff = async (uid, role) => {\r\n    if (!confirm(`Delete ${role} record?`)) return;\r\n    await deleteDoc(doc(db, \"users\", uid));\r\n    alert(`${capitalize(role)} record deleted.`);\r\n    loadStaff(\"librarian\", librarianListEl);\r\n};\r\n\r\n// ── Logout ───────────────────────────────────────────────────\r\nwindow.logout = async () => {\r\n    try {\r\n        await signOut(auth);\r\n        window.location.href = \"#/index.html\";\r\n    } catch (error) {\r\n        alert(\"Logout failed.\");\r\n    }\r\n};\r\n\r\nfunction capitalize(str) {\r\n    return str.charAt(0).toUpperCase() + str.slice(1);\r\n}\r\n"},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
